:root {
  --bg-card: #1a1a2e;
  --bg-header: #16213e;
  --bg-showcase: #0f3460;
  --bg-gem-display: #1a1a2e;
  --bg-bid-current: #e94560;
  --bg-bid-alt: #16213e;
  --bg-footer: #0d0d1a;
  --bg-btn-bid: #e94560;
  --bg-btn-watch: transparent;
  --color-lot: #a0a8c0;
  --color-live: #4ecca3;
  --color-gem-name: #ffffff;
  --color-origin: #a0a8c0;
  --color-spec-label: #7a84a0;
  --color-spec-val: #e0e4f0;
  --color-bid-label: rgba(255,255,255,0.65);
  --color-bid-amount-current: #ffffff;
  --color-bid-amount-alt: #e0e4f0;
  --color-timer-label: #a0a8c0;
  --color-timer-value: #4ecca3;
  --color-btn-bid: #ffffff;
  --color-btn-watch: #a0a8c0;
  --color-facet1: #4ecca3;
  --color-facet2: #53d8f5;
  --color-facet3: #2a9d8f;
  --border-card: #2a2a4a;
  --border-watch-btn: #3a3a5a;
}

.auction-card {
  width: 480px;
  background: var(--bg-card);
  border: 1px solid var(--border-card);
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-size: 14px;
}

.card-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border-card);
}

.lot-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--color-lot);
  text-transform: uppercase;
}

.status-live {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--color-live);
}

.gem-showcase {
  background: var(--bg-showcase);
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 16px;
  padding: 16px;
}

.gem-display {
  background: var(--bg-gem-display);
  width: 96px;
  height: 96px;
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin: 0;
  border: 2px solid var(--color-facet1);
  position: relative;
  gap: 6px;
}

.gem-icon {
  font-size: 36px;
  line-height: 1;
}

.gem-facets {
  display: flex;
  gap: 4px;
}

.facet {
  width: 8px;
  height: 4px;
  border-radius: 2px;
}

.f1 { background: var(--color-facet1); }
.f2 { background: var(--color-facet2); }
.f3 { background: var(--color-facet3); }

.gem-meta {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.gem-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-gem-name);
  margin: 0;
  line-height: 1.2;
}

.gem-origin {
  font-size: 12px;
  color: var(--color-origin);
  margin: 0;
}

.gem-specs {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px 12px;
}

.gem-specs li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 6px;
}

.spec-label {
  font-size: 11px;
  color: var(--color-spec-label);
  font-weight: 500;
}

.spec-val {
  font-size: 11px;
  color: var(--color-spec-val);
  font-weight: 600;
}

.bid-section {
  display: flex;
  flex-direction: row;
  border-top: 1px solid var(--border-card);
}

.bid-block {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 8px;
  gap: 3px;
}

.bid-block.current {
  background: var(--bg-bid-current);
}

.bid-block.estimate,
.bid-block.bids {
  background: var(--bg-bid-alt);
  border-left: 1px solid var(--border-card);
}

.bid-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-bid-label);
}

.bid-block.current .bid-amount {
  font-size: 16px;
  font-weight: 800;
  color: var(--color-bid-amount-current);
}

.bid-block.estimate .bid-amount,
.bid-block.bids .bid-amount {
  font-size: 16px;
  font-weight: 700;
  color: var(--color-bid-amount-alt);
}

.card-footer {
  background: var(--bg-footer);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  gap: 10px;
  border-top: 1px solid var(--border-card);
}

.timer-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.timer-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-timer-label);
}

.timer-value {
  font-size: 18px;
  font-weight: 800;
  color: var(--color-timer-value);
  letter-spacing: 0.04em;
}

.bid-btn {
  background: var(--bg-btn-bid);
  color: var(--color-btn-bid);
  border: none;
  border-radius: 8px;
  padding: 10px 24px;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  letter-spacing: 0.04em;
}

.watch-btn {
  background: var(--bg-btn-watch);
  color: var(--color-btn-watch);
  border: 1px solid var(--border-watch-btn);
  border-radius: 8px;
  padding: 10px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
